// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Ensure the random result is 1 (loss case) by manipulating block.timestamp and block.difficulty
        // We want the modulo result to be 1, so seed is odd
        vm.assume(seed % 2 == 1);
        // Use seed to set block.timestamp (any value) - cannot directly control block.difficulty in foundry, but we can use vm.warp
        vm.warp(seed);
        // Set the difficulty by manipulating the coinbase? Not possible, so we rely on the assumption that seed is odd
        // But to be deterministic, we can use vm.assume on the actual computation: keccak256(abi.encodePacked(block.timestamp, block.difficulty)) % 2 == 1
        // However, block.difficulty is fixed by the test runner. Instead, we can precompute using vm.roll to change block number which affects block.difficulty? No.
        // Alternative: use a loop to find a timestamp that gives result 1 with current block.difficulty.
        // For simplicity, we assume that with block.difficulty=0 (default), a timestamp of 0 gives 1.
        vm.warp(0);
        // Now call play with exact amount
        c.play{value: 10}();
        // Assert that pot has increased by 10 (the msg.value) from its previous value
        assertTrue(c.pot() == 10);
    }
}

