// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 seed) public {
        vm.assume(seed % 2 == 1);
        vm.warp(seed);
        vm.warp(0);
        c.play{value: 10}();
        assertTrue(c.pot() == 10);
    }
}
